    # Find the 5x5 all-1 block
    block = None
    for r in range(H - 4):
        for c in range(W - 4):
            ok = True
            for i in range(5):
                for j in range(5):
                    if grid[r + i][c + j] != 1:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                block = (r, c)
                break
        if block is not None:
            break

    if block is None:
        return grid

    r0, c0 = block

    # Determine the target nonzero color around the 1-block
    freq = {}
    for i in range(-1, 6):
        for j in range(-1, 6):
            rr, cc = r0 + i, c0 + j
            if 0 <= rr < H and 0 <= cc < W:
                if 1 <= i <= 5 and 1 <= j <= 5:
                    continue
                v = grid[rr][cc]
                if v not in (0, 1):
                    freq[v] = freq.get(v, 0) + 1
    target_color = max(freq, key=freq.get) if freq else 1

    n = 7

    def transforms():
        return [
            lambda i, j: (i, j),                     # identity
            lambda i, j: (j, n - 1 - i),            # rot90
            lambda i, j: (n - 1 - i, n - 1 - j),    # rot180
            lambda i, j: (n - 1 - j, i),            # rot270
            lambda i, j: (i, n - 1 - j),            # flip horizontal
            lambda i, j: (n - 1 - i, j),            # flip vertical
            lambda i, j: (j, i),                    # main diagonal
            lambda i, j: (n - 1 - j, n - 1 - i),    # anti-diagonal
        ]

    # Build inverse maps for each transform
    inv_maps = []
    for f in transforms():
        inv = [[None] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                ii, jj = f(i, j)
                inv[ii][jj] = (i, j)
        inv_maps.append(inv)

    # Known ring cells around the missing 5x5
    ring = []
    for i in range(n):
        for j in range(n):
            if 1 <= i <= 5 and 1 <= j <= 5:
                continue
            rr, cc = r0 + i - 1, c0 + j - 1
            if 0 <= rr < H and 0 <= cc < W:
                ring.append((i, j, grid[rr][cc]))

    best = None
    best_score = -1

    # Search candidate 5x5 patches elsewhere
    for rr in range(H):
        for cc in range(W):
            # Candidate inner 5x5 must be in bounds
            if rr + 4 >= H or cc + 4 >= W:
                continue

            # Candidate inner patch should use only 0 and target_color, and no 1s
            valid_inner = True
            for i in range(5):
                for j in range(5):
                    v = grid[rr + i][cc + j]
                    if v == 1 or v not in (0, target_color):
                        valid_inner = False
                        break
                if not valid_inner:
                    break
            if not valid_inner:
                continue

            for inv in inv_maps:
                ok = True
                score = 0

                for ti, tj, tv in ring:
                    qi, qj = inv[ti][tj]
                    gr, gc = rr + qi - 1, cc + qj - 1
                    if not (0 <= gr < H and 0 <= gc < W):
                        ok = False
                        break
                    if grid[gr][gc] != tv:
                        ok = False
                        break
                    score += 1

                if not ok:
                    continue

                out = [[0] * 5 for _ in range(5)]
                possible = True
                for i in range(1, 6):
                    for j in range(1, 6):
                        qi, qj = inv[i][j]
                        gr, gc = rr + qi - 1, cc + qj - 1
                        if not (0 <= gr < H and 0 <= gc < W):
                            possible = False
                            break
                        out[i - 1][j - 1] = grid[gr][gc]
                    if not possible:
                        break

                if possible and score > best_score:
                    best_score = score
                    best = out

    if best is not None:
        return best

    # Fallback: infer each missing cell from symmetric neighbors around the block
    out = [[target_color] * 5 for _ in range(5)]
    for i in range(5):
        for j in range(5):
            vals = []
            candidates = [
                (r0 - 1 - i, c0 + j),     # vertical mirror upward
                (r0 + i, c0 - 1 - j),     # horizontal mirror leftward
                (r0 + 5 + i, c0 + j),     # downward
                (r0 + i, c0 + 5 + j),     # rightward
            ]
            for rr, cc in candidates:
                if 0 <= rr < H and 0 <= cc < W and grid[rr][cc] in (0, target_color):
                    vals.append(grid[rr][cc])
            if vals:
                out[i][j] = max(set(vals), key=vals.count)
    return out

